namespace Notifications;

/// <summary>Computes the backoff delay before the next delivery attempt.</summary>
public sealed class RetryPolicy
{
    private const int MaximumDelay = 3600;

    public int NextDelay(int attempt, Channel channel, bool serverBusy)
    {
        if (attempt <= 0) return 0;
        if (attempt > 10) return MaximumDelay;

        var delay = BaseDelay(channel) * attempt;
        return AdjustDelay(delay, attempt, serverBusy);
    }

    private static int BaseDelay(Channel channel) => channel switch
    {
        Channel.Email => 30,
        Channel.Sms   => 10,
        Channel.Push  => 5,
        _             => 15
    };

    private static int AdjustDelay(int delay, int attempt, bool serverBusy)
    {
        if (serverBusy && delay < 600) delay *= 2;
        if (delay > MaximumDelay) return MaximumDelay;
        if (delay < 1) return 1;
        return attempt > 7 ? delay + 100 : delay;
    }
}
